begin;
create or replace function public.client_portal_data() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('clients',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'agency',o.name)) from public.agency_clients c join public.organizations o on o.id=c.organization_id where public.has_client_portal(c.id)),'[]'::jsonb),'presentations',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'client_id',s.client_id,'snapshot',s.snapshot,'shared_at',s.shared_at,'pipeline_status',(select p.status from public.candidate_placements p where p.id=s.placement_id),'employment',(select jsonb_build_object('starts_on',e.starts_on,'ends_on',e.ends_on) from public.placement_employment e where e.placement_id=s.placement_id),'feedback',coalesce((select jsonb_agg(jsonb_build_object('action',f.action,'note',f.note,'proposed_at',f.proposed_at,'created_at',f.created_at) order by f.created_at desc) from public.client_feedback f where f.presentation_id=s.id),'[]'::jsonb)) order by s.shared_at desc) from public.client_presentations s where s.revoked_at is null and public.has_client_portal(s.client_id)),'[]'::jsonb))$$;
commit;
